def _save(self) -> None:
    self.settings.setValue("playlists", json.dumps(self.items))
    self.settings.setValue("active_playlist", self.active_id)

FILE_MODE = 0o600
FOLDER_MODE = 0o700


def _narrow(path: str, mode: int) -> None:
    now = stat.S_IMODE(os.stat(path).st_mode)
    if now & ~mode:
        os.chmod(path, now & mode)


def keep_private(path: str, *, folder: bool = True, create: bool = True) -> bool:
    """*path* readable by this user alone, and with *folder* the folder it is
    in too (made at 0700 when missing). *create*: a missing file made empty
    at 0600 first. Never raises; False when it could not be done (logged)."""
    if os.name != "posix" or not path:
        return True
    try:
        if folder:
            parent = os.path.dirname(path)
            os.makedirs(parent, mode=FOLDER_MODE, exist_ok=True)
            _narrow(parent, FOLDER_MODE)
        if create and not os.path.lexists(path):
            try:
                os.close(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, FILE_MODE))
            except FileExistsError:
                pass
        if os.path.exists(path):
            _narrow(path, FILE_MODE)
        return True
    except OSError as e:
        log.warning("settings: %s not kept to this user (%s)", path, e)
        return False

def redact_text(text: str) -> str:
    """*text* the app did not write - a line ffmpeg or mpv printed, an
    exception's message - safe to log: every address in it masked
    (_address_masked), then every registered value. Never raises."""
    try:
        if "://" in text:
            text = URL_IN_TEXT.sub(lambda m: _address_masked(m.group(0)), text)
    except Exception:
        pass
    return redact(text)

class _RedactFilter(logging.Filter):
    """The safety net: every record masked, whether or not the call site
    remembered to - the addresses in it (an ffmpeg or mpv line quoting a
    stream's address with its token or login, redact_text) and the
    registered values, in its message, its arguments and the traceback it
    carries (exc_info). Failure here must lose nothing, so any error leaves
    the record as it was."""

    def filter(self, record: logging.LogRecord) -> bool:
        try:
            if record.args:
                # Formatted first, then masked whole: an address can be
                # split between the message and an argument, and masking
                # the message alone could eat a %s an argument needs.
                text = record.getMessage()
                record.msg, record.args = redact_text(text), ()
            else:
                record.msg = _redact_arg(record.msg)
        except Exception:
            pass
        try:
            # Formatted here, once, masked: every handler's formatter uses
            # exc_text when it is there instead of formatting it again.
            if record.exc_info and not record.exc_text:
                record.exc_text = logging.Formatter().formatException(record.exc_info)
            if record.exc_text:
                record.exc_text = redact_text(record.exc_text)
            if record.stack_info:
                record.stack_info = redact_text(record.stack_info)
        except Exception:
            pass
        return True

def secure(url: str) -> bool:
    """Whether a request to one of dopeiptv.org's services may go to *url*:
    https - or this computer, for the tests' own servers. Anything else is
    refused before a connection is made (a changed endpoint, a typo)."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(str(url))
        host = parts.hostname
    except ValueError:
        return False
    return parts.scheme == "https" or (
        parts.scheme == "http" and host in ("127.0.0.1", "localhost", "::1"))

def new_code() -> tuple[str, str]:
    """(code, its SHA-256): the code stays on this computer, the hash goes
    with the report - the one link between the two, naming nobody."""
    import hashlib
    import secrets
    code = secrets.token_urlsafe(24)
    return code, hashlib.sha256(code.encode("ascii")).hexdigest()


def code_hash(code: str) -> str:
    import hashlib
    return hashlib.sha256(code.encode("ascii")).hexdigest()

def fetch_replies(codes: list[str], timeout: float = 15.0, endpoint: str | None = None) -> dict | None:
    """{code: [answers]} for the codes whose reports were answered; None
    when the site could not be asked (never from a modified build). Only
    the hashes are sent."""
    if not build_check.allowed():
        return None
    by_hash = {code_hash(c): c for c in codes[:20]}
    try:
        status, data = _post(endpoint or REPLIES, json.dumps({"codes": list(by_hash)}).encode("utf-8"), timeout)
        if status != 200:
            raise OSError(f"HTTP {status}")
        got = json.loads(data or b"{}").get("replies") or {}
    except Exception as e:
        log.info("report: answers not asked (%s)", type(e).__name__)
        return None
    return {by_hash[h]: a for h, a in got.items() if h in by_hash and isinstance(a, list)}

def _answers_reply(self, code: str, text: str) -> None:
    """The person's reply to the answer that lets them, from its card:
    sent as feedback with the report's own code hash as its thread -
    scrubbed as feedback is, within feedback's limits, never from a
    modified build - and kept on the report here once the site took it;
    asked about soon after, as a new report is. The site saying the
    thread is closed (409) closes it here too."""
    settings = getattr(self, "settings", None)
    dlg = self._answers_window()
    if settings is None or not build_check.allowed():
        return
    now = time.time()
    wait = report.feedback_wait(report.sent_times(settings.value("feedback_sent", "")), now)
    if wait:
        if dlg is not None:
            dlg.reply_failed(code, wait)
        return
    words = report.scrub(text, self._personal_values()).strip()[:report.REPLY_MAX]
    if not words:
        return
    h = report.code_hash(code)
    fields = {"reply": h, "thread": h}
    if self._supporter_now():
        fields["supporter"] = "yes"
    if dlg is not None:
        dlg.reply_sending(code)

    def done(status) -> None:
        win = self._answers_window()
        items = report.tickets(settings)
        ticket = next((t for t in items if t.get("c") == code), None)
        if status and 200 <= status < 300:
            at = time.time()
            keep = [t for t in report.sent_times(settings.value("feedback_sent", "")) if at - t < 86400]
            settings.setValue("feedback_sent", ",".join(str(int(t)) for t in [*keep, at]))
            if ticket is not None:
                report.add_followup(ticket, words, at)
                report.save_tickets(settings, items)
            self._schedule_answers()            # two minutes from now, as after a report
            if win is not None:
                win.reply_sent(code, report.tickets(settings))
            self._show_toast(tr("fba_reply_sent"), 5000)
            log.info("report: a reply to an answer sent by the person")
            return
        if status == 409:
            if ticket is not None and report.close_thread(ticket):
                report.save_tickets(settings, items)
            if win is not None:
                win.reply_failed(code, "closed", report.tickets(settings))
            return
        if win is not None:
            win.reply_failed(code, "failed")
    run_async(self.pool, partial(report.send_status, "feedback", words, extra=fields), done,
              lambda _e=None: done(0))

def accept(stats_dir: str, body: dict, build: str = "unknown") -> tuple[int, dict]:
    """One report from the app; (status, answer). *build*: what its
    X-dopeIPTV-Build header said (official.kind), never the body's word. A
    report already taken answers ok with "duplicate" (the app need not try
    again), and is not kept twice.

    With "thread" (a report's code hash) it is a follow-up to that report's
    latest answer: taken only while that answer lets them reply and they
    have not yet (409 "closed" otherwise, nothing kept); kept as a row of
    its own, tied to the report by its id, never by the hash."""
    thread = str(body.get("thread") or "")
    if thread and not _HASH.match(thread):
        return 400, {"error": "thread"}
    kind = "feedback" if thread else str(body.get("kind") or "feedback")
    if kind not in KINDS:
        kind = "feedback"
    version = str(body.get("version") or "")
    if not _VERSION.match(version):
        version = "?"
    system = re.sub(r"[^A-Za-z0-9 ._-]", "", str(body.get("os") or ""))[:24] or "?"
    site = kind == "feedback" and not thread and body.get("from") == "site"
    most = THREAD_TEXT if thread else MAX_TEXT
    # Cut before it is cleaned, with room for what the cleaning shortens
    # (an address to <address>), then again to what is kept.
    text = _cut(scrub(_head(str(body.get("text") or "").lstrip(), 2 * most)).strip()[:most],
                THREAD_BYTES if thread else SITE_BYTES if site else MAX_BYTES)
    if not text:
        return 400, {"error": "empty"}
    now = time.time()
    row = {"id": uuid.uuid4().hex[:12], "t": int(now), "kind": kind,
           "version": version, "os": system, "build": build if build in BUILDS else "unknown",
           "sig": "" if thread else signature(kind, text), "text": text}
    if not thread and _HASH.match(str(body.get("reply") or "")):
        row["reply"] = str(body["reply"])
    if body.get("supporter") == "yes":
        # From someone whose app holds a supporter key: read first. Only the
        # word comes, never the key, so it names nobody.
        row["sup"] = 1
    if kind == "feedback" and not thread:
        row.update({k: str(body.get(k)) for k, allowed in CHOICES.items() if body.get(k) in allowed})
        if site:
            row["from"] = "site"
    os.makedirs(stats_dir, exist_ok=True)
    path, _state = _paths(stats_dir)
    make_room(stats_dir)
    with _LOCK:
        try:
            if os.path.getsize(path) >= MAX_FILE:
                # Nothing could go (no report in it can be read): never past it.
                return 503, {"error": "full"}
        except OSError:
            pass
        mem = _memory(stats_dir, now)
        rid = to = None
        if thread:
            rid, to = _thread_of(stats_dir, thread)
            if rid is None:
                return 409, {"error": "closed"}
        same = _same(kind, text, rid or "")
        if same in mem["hashes"]:
            return 200, {"ok": True, "duplicate": True}
        if thread:
            if to is None:
                return 409, {"error": "closed"}
            row.update(thread_of=rid, to=to)
        if mem["n"] >= DAY_MOST:
            return 429, {"error": "enough for today"}
        sig = row["sig"]
        if kind != "feedback" and mem["sigs"].get(sig, 0) >= SAME_SIG_DAY:
            # Counted, so the problem's number stays right; its text is
            # already here many times over today.
            row["text"], row["counted"] = "", True
        elif mem["bytes"] + _bytes(row["text"]) > DAY_BYTES:
            # The day's room is used up (many long reports, or someone
            # filling it): this one keeps its start, enough to read it by.
            short = _cut(row["text"], LATE_BYTES)
            if short != row["text"]:
                row["text"], row["cut"] = short.rstrip() + " …", True
        mem["hashes"][same] = now
        mem["n"] += 1
        mem["sigs"][sig] = mem["sigs"].get(sig, 0) + 1
        mem["bytes"] += _bytes(row["text"])
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row, ensure_ascii=False) + "\n")
    if rid:
        # A reply waits to be read: out of the archive, unread (its own id
        # has no mark yet).
        archive(stats_dir, rid, False)
    return 200, {"ok": True, "id": row["id"]}

def format_code(raw: bytes) -> str:
    """32 bytes as base32 in groups of four: 13 groups."""
    text = base64.b32encode(raw).decode("ascii").rstrip("=")
    return "-".join(text[i:i + 4] for i in range(0, len(text), 4))


def new_code() -> str:
    return format_code(secrets.token_bytes(32))

def seal(key: bytes, doc: dict[str, Any]) -> bytes:
    """The snapshot as the site keeps it: a format byte, a random nonce and
    the compressed JSON, encrypted and authenticated."""
    plain = zlib.compress(_canon(doc).encode("utf-8"), 6)
    nonce = secrets.token_bytes(12)
    head = bytes([FORMAT])
    return head + nonce + aead.encrypt(key, nonce, plain, _AAD + head)


def unseal(key: bytes, blob: bytes) -> dict[str, Any]:
    if not blob:
        raise SyncError("read")
    if blob[0] > FORMAT:
        raise SyncError("newer")
    if blob[0] != FORMAT or len(blob) < 1 + 12 + 16:
        raise SyncError("read")
    try:
        plain = aead.decrypt(key, blob[1:13], blob[13:], _AAD + blob[:1])
        inflate = zlib.decompressobj()
        text = inflate.decompress(plain, _MAX_PLAIN)
        if inflate.unconsumed_tail:
            raise ValueError("too big")
        doc = json.loads(text.decode("utf-8"))
    except (ValueError, zlib.error, UnicodeDecodeError) as e:
        raise SyncError("read") from e
    if not isinstance(doc, dict) or not isinstance(doc.get("c"), dict):
        raise SyncError("read")
    if int(doc.get("v") or 0) > FORMAT:
        raise SyncError("newer")
    clean = empty_doc()
    for cat, entries in doc["c"].items():
        if isinstance(entries, dict):
            clean["c"][str(cat)] = {
                str(k): e for k, e in entries.items()
                if isinstance(e, dict) and isinstance(e.get("t"), int)
                and ("v" in e or e.get("d") == 1)}
    return clean

def poly1305(key: bytes, msg: bytes) -> bytes:
    """The 16-byte Poly1305 tag of *msg* under the one-time *key* (2.5)."""
    if len(key) != 32:
        raise ValueError("Poly1305 takes a 32-byte key")
    r = int.from_bytes(key[:16], "little") & _CLAMP
    s = int.from_bytes(key[16:], "little")
    acc = 0
    p = _P1305
    full = len(msg) - len(msg) % 16
    pad = 1 << 128
    for i in range(0, full, 16):
        acc = (acc + int.from_bytes(msg[i:i + 16], "little") + pad) * r % p
    if full < len(msg):
        rest = msg[full:]
        acc = (acc + int.from_bytes(rest, "little") + (1 << (8 * len(rest)))) * r % p
    return ((acc + s) & ((1 << 128) - 1)).to_bytes(16, "little")


def _pad16(n: int) -> bytes:
    return b"\0" * (-n % 16)


def _tag(key: bytes, nonce: bytes, aad: bytes, ct: bytes) -> bytes:
    otk = block(key, nonce, 0)[:32]
    mac = b"".join((aad, _pad16(len(aad)), ct, _pad16(len(ct)),
                    struct.pack("<QQ", len(aad), len(ct))))
    return poly1305(otk, mac)


def encrypt(key: bytes, nonce: bytes, plaintext: bytes, aad: bytes = b"") -> bytes:
    """The ciphertext with its 16-byte tag after it (2.8)."""
    ct = chacha20(key, nonce, 1, plaintext)
    return ct + _tag(key, nonce, aad, ct)


def decrypt(key: bytes, nonce: bytes, data: bytes, aad: bytes = b"") -> bytes:
    """The plaintext; ValueError when the tag does not match (a changed
    byte, the wrong key or nonce or aad)."""
    if len(data) < 16:
        raise ValueError("too short for a Poly1305 tag")
    ct, tag = data[:-16], data[-16:]
    if not hmac.compare_digest(_tag(key, nonce, aad, ct), tag):
        raise ValueError("the data does not check out")
    return chacha20(key, nonce, 1, ct)

def keep_private(path: str, *, folder: bool = True, create: bool = True) -> bool:
    """*path* readable by this user alone, and with *folder* the folder it is
    in too (made at 0700 when missing). *create*: a missing file made empty
    at 0600 first. Never raises; False when it could not be done (logged)."""
    if os.name != "posix" or not path:
        return True
    try:
        if folder:
            parent = os.path.dirname(path)
            os.makedirs(parent, mode=FOLDER_MODE, exist_ok=True)
            _narrow(parent, FOLDER_MODE)
        if create and not os.path.lexists(path):
            try:
                os.close(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, FILE_MODE))
            except FileExistsError:
                pass
        if os.path.exists(path):
            _narrow(path, FILE_MODE)
        return True
    except OSError as e:
        log.warning("settings: %s not kept to this user (%s)", path, e)
        return False


def protect(stores: Mapping[str, Any] | None = None) -> None:
    """Every settings file of the app kept to this user (core/backup's
    open_stores: the main settings, resume, follow, cache). Never in the way
    of starting."""
    if os.name != "posix":
        return
    try:
        from PyQt6.QtCore import QSettings

        from .. import ORG
        if stores is None:
            from .backup import open_stores
            stores = open_stores()
        for s in stores.values():
            path = str(s.fileName())
            plain = s.format() == QSettings.Format.IniFormat or sys.platform != "darwin"
            own = os.path.basename(os.path.dirname(path)) == ORG
            keep_private(path, folder=plain and own, create=plain)
    except Exception as e:
        log.warning("settings: not kept to this user (%s)", e)

def __init__(self, slot: str, endpoint: str | None = None,
             timeout: float = 20.0) -> None:
    self.url = (endpoint or ENDPOINT) + slot
    self.timeout = timeout
    from .. import __version__
    self.headers = {"User-Agent": f"dopeIPTV/{__version__}",
                    "Content-Type": "application/json", **build_check.headers()}

def _call(self, method: str, body: dict | None = None) -> Any:
    from ._lazy_requests import requests
    if not build_check.allowed():
        # Never asked from a modified build: the site refuses it anyway.
        raise SyncError("modified")
    if not build_check.secure(self.url):
        log.warning("sync: not https - nothing sent")
        raise SyncError("net")
    try:
        # Never followed elsewhere: a copy goes to the slot named, or
        # nowhere.
        return requests.request(method, self.url, headers=self.headers,
                                data=None if body is None
                                else json.dumps(body).encode("ascii"),
                                timeout=self.timeout, allow_redirects=False)
    except Exception as e:
        log.info("sync: %s not answered (%s)", method, type(e).__name__)
        raise SyncError("net") from e

def secure(url: str) -> bool:
    """Whether a request to one of dopeiptv.org's services may go to *url*:
    https - or this computer, for the tests' own servers. Anything else is
    refused before a connection is made (a changed endpoint, a typo)."""
    from urllib.parse import urlsplit
    try:
        parts = urlsplit(str(url))
        host = parts.hostname
    except ValueError:
        return False
    return parts.scheme == "https" or (
        parts.scheme == "http" and host in ("127.0.0.1", "localhost", "::1"))

class Refused(Exception):
    """The slot is bound to a credential and the request did not carry it."""


def _seal(auth: str) -> str:
    """What is kept of a credential: its SHA-256."""
    return hashlib.sha256(auth.encode("ascii")).hexdigest()


def _check(data: dict | None, auth: str) -> None:
    """Refused unless the slot is unbound or *auth* is its credential."""
    kept = data.get("auth") if data else None
    if kept and not (auth and hmac.compare_digest(_seal(auth), str(kept))):
        raise Refused()

def get(stats_dir: str, slot: str, auth: str = "") -> dict | None:
    """{"version", "t", "blob"} kept under *slot*, or None. Refused when
    the slot is bound and *auth* is not its credential."""
    path = _path(stats_dir, slot)
    with _lock(slot):
        data = _read(path)
        if data is None:
            return None
        _check(data, auth)
        try:
            if time.time() - os.path.getmtime(path) > TOUCH_SECS:
                os.utime(path)
        except OSError:
            pass
    return {"version": data["version"], "t": int(data.get("t") or 0), "blob": data["blob"]}


def put(stats_dir: str, slot: str, version_seen: object, blob: object,
        auth: str = "") -> tuple[int, dict]:
    """Keep *blob* as the next version of *slot* - if *version_seen* is the
    version kept now (0: none yet). A new slot is refused while all the
    slots keep MAX_TOTAL; one there already can still be written. A bound
    slot takes only its credential (403, before anything of it is said);
    an unbound one is bound to *auth* when one comes. (status, body to
    answer)."""
    path = _path(stats_dir, slot)
    if not isinstance(version_seen, int) or isinstance(version_seen, bool) or version_seen < 0:
        return 400, {"error": "version_seen"}
    size = blob_size(blob)
    if size > MAX_BLOB:
        return 413, {"error": "too big", "most": MAX_BLOB}
    if size < MIN_BLOB:
        return 400, {"error": "blob"}
    with _lock(slot):
        cur = _read(path)
        try:
            _check(cur, auth)
        except Refused:
            return 403, {"error": "refused"}
        version = cur["version"] if cur else 0
        if version_seen != version:
            body: dict = {"error": "conflict", "version": version,
                          "t": int(cur.get("t") or 0) if cur else 0}
            if cur:
                body["blob"] = cur["blob"]
            return 409, body
        if cur is None and usage(stats_dir)["bytes"] + size > MAX_TOTAL:
            return 507, {"error": "full"}
        before = _size(path) if cur else 0
        grows = len(str(blob)) - len(cur["blob"]) if cur else 0
        if grows > 0 and usage(stats_dir)["bytes"] + grows > MAX_TOTAL * GROW_SHARE:
            # Rewritten no larger it would still be taken: a household that
            # syncs goes on syncing while the space is full.
            return 507, {"error": "full"}
        now = int(time.time())
        kept = {"version": version + 1, "t": now, "blob": blob}
        bound = (cur or {}).get("auth") or (_seal(auth) if auth else "")
        if bound:
            kept["auth"] = bound
        _write(path, kept)
        _changed(stats_dir, _size(path) - before, 0 if cur else 1)
    return 200, {"version": version + 1, "t": now}


def delete(stats_dir: str, slot: str, auth: str = "") -> bool:
    """Remove *slot*. Refused when it is bound and *auth* is not its
    credential."""
    path = _path(stats_dir, slot)
    with _lock(slot):
        _check(_read(path), auth)
        size = _size(path)
        try:
            os.unlink(path)
        except FileNotFoundError:
            return False
        _changed(stats_dir, -size, -1)
        return True

def _sync(self) -> None:
    """Someone's encrypted copy under a slot (sync.py), for anyone: no
    key, no account (a supporter key an older app still sends is not
    read). The address is never kept, logged or tied to the slot: the
    limits hold it in memory only."""
    if self._refused("sync"):
        return
    import sync
    slot = self.path.split("?", 1)[0][len(SYNC):]
    if not sync.SLOT.match(slot):
        return self._send(404, {"error": "not found"})
    addr = self.headers.get("X-Real-IP") or "local"
    if not _allowed("sync:" + addr, SYNC_PER_WINDOW):
        return self._send(429, {"error": "slow down"})
    if self.command != "GET" and not _allowed("sync-w:" + addr, SYNC_WRITES_PER_WINDOW):
        return self._send(429, {"error": "slow down"})
    where = _stats_dir()
    auth = self.headers.get("X-Sync-Auth") or ""
    if auth and not sync.AUTH.match(auth):
        return self._send(400, {"error": "auth"})
    try:
        if self.command == "GET":
            got = sync.get(where, slot, auth)
            return self._send(200, got) if got else self._send(404, {"error": "none"})
        if self.command == "DELETE":
            return self._send(200, {"deleted": sync.delete(where, slot, auth)})
    except sync.Refused:
        return self._send(403, {"error": "refused"})
    try:
        length = int(self.headers.get("Content-Length") or 0)
    except ValueError:
        length = -1
    if length > sync.MAX_BODY:
        self.close_connection = True
        return self._send(413, {"error": "too big", "most": sync.MAX_BLOB})
    if length <= 0:
        return self._send(400, {"error": "body"})
    try:
        data = json.loads(self.rfile.read(length))
    except (ValueError, TypeError, RecursionError):
        return self._send(400, {"error": "body"})
    if not isinstance(data, dict):
        return self._send(400, {"error": "body"})
    if not sync.exists(where, slot) and not _allowed("sync-new:" + addr, SYNC_NEW_PER_DAY, DAY):
        return self._send(429, {"error": "slow down"})
    try:
        status, body = sync.put(where, slot, data.get("version_seen"), data.get("blob"), auth)
    except OSError as e:
        print(f"[donate] sync: not stored ({type(e).__name__})", file=sys.stderr, flush=True)
        return self._send(503, {"error": "not stored"})
    if status == 200:
        try:
            sync_watch(where)
        except Exception as e:  # noqa: BLE001 - a warning never stops a write
            print(f"[donate] sync space: {type(e).__name__}", file=sys.stderr, flush=True)
    return self._send(status, body)

# Settings sync from the app (donate/sync.py): a body of up to 3 MB
# (nginx's default is 1 MB), held in memory, and not logged - a slot and
# an address together would say which computers belong together. The
# content host limits the rate; here at most 8 copies come in at once
# from one address (dopeiptv_sync_put: PUTs only), 24 MB of memory.
location ^~ /sync/ {
    proxy_pass http://CONTENT_HOST:8081;   # <-- the same address as below
    client_max_body_size 3m;
    client_body_buffer_size 3m;
    access_log off;
    limit_conn conn_limit 64;
    limit_conn dopeiptv_sync_put 8;
    limit_conn_status 429;
    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host  $host;
    proxy_set_header X-Forwarded-Port  443;
}

def new_code() -> str:
    raw = "".join(secrets.choice(ALPHABET) for _ in range(CODE_LEN))
    return format_code(raw)

@functools.lru_cache(maxsize=8)
def derive(code: str) -> tuple[str, bytes]:
    """(room id, key) for a code: the name the relay keeps the room's
    messages under (64 hex) and the key they are sealed with, each from its
    own HKDF label - one says nothing about the other."""
    shown = parse_code(code)
    if shown is None:
        raise ValueError("not a room code")
    raw = shown.replace("-", "")
    rounds = OLD_STRETCH if len(raw) == OLD_LEN else STRETCH
    seed = hashlib.pbkdf2_hmac("sha256", raw.encode("ascii"), _SALT, rounds, 32)
    return hkdf(seed, _SALT, b"room", 32).hex(), hkdf(seed, _SALT, b"key", 32)

def seal(key: bytes, room: str, msg: dict[str, Any]) -> bytes:
    """*msg* as the relay passes it: a format byte, a random nonce, and the
    padded JSON, encrypted and tied to the room."""
    text = json.dumps(msg, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    size = next((p for p in _PAD if p >= len(text) + 2), 0)
    if not size:
        raise ValueError("message too long")
    plain = struct.pack(">H", len(text)) + text + b"\0" * (size - 2 - len(text))
    nonce = secrets.token_bytes(12)
    head = bytes([FORMAT])
    return head + nonce + aead.encrypt(key, nonce, plain, _AAD + head + bytes.fromhex(room))


def open_frame(key: bytes, room: str, blob: bytes) -> dict[str, Any] | None:
    """The message in *blob*, or None for anything that is not one of this
    room's (another key, damaged, a newer format)."""
    if not isinstance(blob, (bytes, bytearray)) or not MIN_FRAME <= len(blob) <= MAX_FRAME:
        return None
    if blob[0] != FORMAT:
        return None
    try:
        plain = aead.decrypt(key, bytes(blob[1:13]), bytes(blob[13:]),
                             _AAD + bytes(blob[:1]) + bytes.fromhex(room))
        (length,) = struct.unpack(">H", plain[:2])
        if length > len(plain) - 2:
            return None
        msg = json.loads(plain[2:2 + length].decode("utf-8"))
    except (ValueError, struct.error, UnicodeDecodeError):
        return None
    return msg if isinstance(msg, dict) else None

# -- out
def _make(self, kind: str, **fields: Any) -> dict[str, Any]:
    self._sent += 1
    msg: dict[str, Any] = {"k": kind, "f": self.me, "n": self._sent, "t": self.clock.now_ms()}
    msg.update({k: v for k, v in fields.items() if v is not None})
    return msg

# -- the requests
def post(self, rid: str, member: str, blob: bytes) -> tuple[int, dict]:
    if not ROOM.match(rid or "") or not MEMBER.match(member or ""):
        return 400, {"error": "room or member"}
    if not isinstance(blob, (bytes, bytearray)) or len(blob) > MAX_MESSAGE:
        return 413, {"error": "too big", "most": MAX_MESSAGE}
    if len(blob) < MIN_MESSAGE:
        return 400, {"error": "message"}
    now = self._clock()
    with self._lock:
        room = self._room(rid, now)
        if room is None:
            return 503, {"error": "busy"}
        if not self._seat(room, member, now):
            return 403, {"error": "full", "most": MAX_MEMBERS}
        room.seq += 1
        room.msgs.append((room.seq, member, bytes(blob)))
        room.size += len(blob)
        while room.msgs and (len(room.msgs) > KEEP_MESSAGES or room.size > ROOM_BYTES):
            room.size -= len(room.msgs.popleft()[2])
        room.cond.notify_all()
        return 200, self._answer(room)

def _together(self) -> None:
    """Watch together's relay (together.py): a room's sealed messages,
    in memory only. Neither the room, the member nor the address is
    kept beyond memory or logged (the rate limit holds the address)."""
    if self._refused("together"):
        return
    import together
    path, _, query = self.path.partition("?")
    room = path[len(TOGETHER):]
    if not together.ROOM.match(room):
        return self._send_quiet(404, {"error": "not found"})
    member = (self.headers.get(together.MEMBER_HEADER) or "").strip().lower()
    if not together.MEMBER.match(member):
        return self._send_quiet(400, {"error": "member"})
    addr = self.headers.get("X-Real-IP") or "local"
    if not _allowed("tg:" + addr, TOGETHER_PER_WINDOW):
        return self._send_quiet(429, {"error": "slow down"})
    # Asking for a room that is not there makes it: without a limit of
    # its own one address filled every room there is (leaving is no room).
    if self.command != "DELETE" and not together.RELAY.has(room) \
            and not _allowed("tg-new:" + addr, TOGETHER_NEW_PER_WINDOW):
        return self._send_quiet(429, {"error": "slow down"})
    if self.command == "GET":
        args = {k: v[0] for k, v in urllib.parse.parse_qs(query).items()}
        try:
            after = int(args.get("after", "0"))
            wait = float(args.get("wait", "0"))
        except ValueError:
            return self._send_quiet(400, {"error": "after or wait"})
        if wait != wait:                     # NaN
            return self._send_quiet(400, {"error": "after or wait"})
        return self._send_quiet(*together.RELAY.poll(room, member, after, wait, addr))
    if self.command == "DELETE":
        return self._send_quiet(*together.RELAY.leave(room, member))
    try:
        length = int(self.headers.get("Content-Length") or 0)
    except ValueError:
        length = -1
    if length > together.MAX_MESSAGE:
        self.close_connection = True
        return self._send_quiet(413, {"error": "too big", "most": together.MAX_MESSAGE})
    if length <= 0:
        return self._send_quiet(400, {"error": "body"})
    blob = self.rfile.read(length)
    return self._send_quiet(*together.RELAY.post(room, member, blob))

# Watch together from the app (donate/together.py): a request waits up
# to 25 s for the room's next message, so the read timeout is longer
# than that and nothing is buffered; not logged - a room and the
# addresses in it would say who watches with whom. The content host
# limits the rate; a long poll holds a connection, hence limit_conn.
location ^~ /together/ {
    proxy_pass http://CONTENT_HOST:8081;   # <-- the same address as below
    client_max_body_size 4k;
    client_body_buffer_size 4k;
    access_log off;
    proxy_read_timeout 50s;
    proxy_buffering off;
    limit_conn conn_limit 64;
    limit_conn_status 429;
    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host  $host;
    proxy_set_header X-Forwarded-Port  443;
}

def set_private(on: bool) -> None:
    global _private
    if on != _private:
        log.info("private viewing %s", "on" if on else "off")
    _private = bool(on)


def private() -> bool:
    return _private

def playback_started(kind: str, key: Any) -> None:
    """The window's player took a stream (or private viewing was turned on
    while one plays): marked private while private viewing is on; anything
    else chosen after it ended is not."""
    global _private_playback
    ident = (str(kind or ""), _key(key))
    if private():
        _private_playback = ident
    elif _private_playback != ident:
        _private_playback = None


def playback_stopped() -> None:
    """Stop: what is played next is a new playback."""
    global _private_playback
    if not private():
        _private_playback = None


def playback_private(kind: str, key: Any) -> bool:
    """Whether the playback (*kind*, *key*) is to be kept to this computer."""
    return private() or _private_playback == (str(kind or ""), _key(key))


def private_key(key: Any) -> bool:
    """Whether a store keeping something of the title *key* - a resume
    point - is to keep nothing: private viewing on, or that title the
    private playback still going on (whatever kind the store calls it)."""
    return private() or (_private_playback is not None and _private_playback[1] == _key(key))


def for_log(text: Any) -> Any:
    """What a log line may say of what is played: its title or name, or
    "<private>" while private viewing is on or a playback that began
    private still goes on after it - the log is kept on disk and goes with
    a report."""
    return "<private>" if _private or _private_playback is not None else text

def record(self, group: str, key, pos: float, dur: float,
           item: dict | None = None,
           series_ctx: dict | None = None) -> None:
    """Store (or drop) a resume point for *group:key*. Positions in the
    first minute or past 95% of the runtime are dropped, not saved - the
    user is effectively at the start or the end. For movies and episodes an
    *item* snapshot is kept (plus the episode's *series_ctx*) so the
    'Continue watching' list can render and replay it."""
    if privacy.private_key(key):
        # Private viewing, or the private playback of this title going
        # on after it ended: where it stopped is not kept - the store's
        # own check, whoever calls.
        return
    rkey = f"{group}:{key}"
    if dur > 0 and 60 < pos < dur * 0.95:
        entry: dict[str, Any] = {"pos": round(pos), "dur": round(dur),
                                 "ts": int(time.time())}
        if group in ("vod", "episode") and item:
            snap = {k: item[k] for k in _SNAP_FIELDS
                    if item.get(k) is not None}
            if snap:
                entry["item"] = snap
            if group == "episode" and series_ctx:
                ctx = {k: series_ctx[k] for k in _CTX_FIELDS
                       if series_ctx.get(k) is not None}
                if ctx:
                    entry["ctx"] = ctx
        else:
            # Preserve any existing snapshot when we only have position.
            old = self._data.get(rkey) or {}
            if old.get("item"):
                entry["item"] = old["item"]
            if old.get("ctx"):
                entry["ctx"] = old["ctx"]
        self._data[rkey] = entry
    else:
        self._data.pop(rkey, None)
    self._settings.setValue(self._key, json.dumps(self._data))

def site_headers(url: str = SITE) -> dict:
    """A request's headers: the user agent, and to dopeiptv.org which kind
    of build asks (core/build_check.py) - the site serves no modified one."""
    out = {"User-Agent": user_agent()}
    if is_site(url):
        out.update(build_check.headers())
    return out

def headers() -> dict[str, str]:
    """What every request to dopeiptv.org carries."""
    return {HEADER: kind()}

def kind() -> str:
    return verdict().kind


def allowed() -> bool:
    """dopeiptv.org's services: on, unless this is a modified build."""
    return kind() != MODIFIED

def why_not(sums: bytes, sig: bytes, keys: tuple[str, ...] = KEYS) -> str:
    """"" when *sums* is signed by one of *keys* and well formed, else why not."""
    if not sums.strip():
        return "the release has no SHA256SUMS"
    try:
        raw = base64.b64decode(sig.strip(), validate=True)
    except (binascii.Error, ValueError):
        return "SHA256SUMS.sig is not base64"
    if not any(ed25519.verify(base64.b64decode(k), sums, raw) for k in keys):
        return "SHA256SUMS is not signed with dopeIPTV's release key"
    try:
        lines = sums.decode("utf-8").splitlines()
    except UnicodeDecodeError:
        return "SHA256SUMS is not text"
    bad = [ln for ln in lines if ln and not _LINE.fullmatch(ln)]
    if bad:
        return f"SHA256SUMS has a line that is not a checksum and a file name: {bad[0][:80]!r}"
    return ""

