class MonthKeys:
    """The keys every mark of a visitor is made with: one per month, random,
    in this service's memory alone - never in a file on a disk, so never in
    a backup or a copy of one, and gone when the service stops. With
    STATS_KEYS_DIR naming a folder on a file system kept in memory (tmpfs)
    they wait there through a restart too; anywhere else that folder is not
    used. A month's key is kept for KEPT_MONTHS months, then forgotten -
    and with it any way from what is kept back to an address. A line of an
    older month gets a key for this run alone."""

    def __init__(self, today: date, folder: str = "", keys: dict | None = None) -> None:
        self.folder = folder if folder and os.path.isdir(folder) and in_memory(folder) else ""
        got = keys if keys is not None else self._read()
        self.keys: dict = {m: bytes.fromhex(k) for m, k in got.items()
                           if isinstance(k, str) and re.fullmatch(r"[0-9a-f]{64}", k)}
        self._passing: dict = {}
        self.roll(today)

    def _read(self) -> dict:
        if not self.folder:
            return {}
        return _load(os.path.join(self.folder, "keys.json"), {})

    def _write(self) -> None:
        if not self.folder:
            return
        with contextlib.suppress(OSError):
            _save(os.path.join(self.folder, "keys.json"), {m: k.hex() for m, k in self.keys.items()})

    def roll(self, today: date) -> None:
        """Today's months kept, the older keys forgotten."""
        self.month = today.strftime("%Y-%m")
        self.kept = tuple(_months_back(self.month, KEPT_MONTHS))
        gone = [m for m in self.keys if m not in self.kept]
        for m in gone:
            del self.keys[m]
        if gone:
            self._write()

    def key(self, month: str) -> bytes:
        if month in self.keys:
            return self.keys[month]
        if month in self.kept:
            self.keys[month] = secrets.token_bytes(32)
            self._write()
            return self.keys[month]
        return self._passing.setdefault(month, secrets.token_bytes(32))

    def known(self, month: str) -> bytes | None:
        """The month's key if one is kept - never one made for the asking."""
        return self.keys.get(month)

    def kid(self, month: str) -> str:
        """A name for the month's key: which kept marks it can open."""
        return hmac.new(self.key(month), b"id", hashlib.sha256).hexdigest()[:8]

def at_rest(v: dict, day: str, state: dict) -> dict:
    """A visit as it is written down. Its visitor named for this day alone
    (day_id: no two days of one visitor alike) beside the mark sealed
    (seal: nothing to anyone without the month's key, which is in memory
    alone), its start to the half hour and what happened in it to ten
    seconds from there, a screen by its kind, the browser's language without
    its country, a link's site and tag as site_of and source_of keep them -
    and nothing else: no address, no page that linked, no exact time, no
    mark of the device."""
    vid = v.get("id") or ""
    if "did" not in v:
        v["did"] = day_id(state, day, vid) if vid and not v.get("_lost") else vid
    if "w" not in v and vid and not v.get("_lost"):
        v["w"], v["e"] = seal(state, day, vid)
    try:
        start = int(v.get("start") or 0)
    except (TypeError, ValueError):
        start = 0
    s0 = start - start % COARSE

    def t(x) -> int:
        try:
            x = int(x)
        except (TypeError, ValueError):
            return s0
        return s0 + max(0, int(round((x - start) / STEP)) * STEP)

    def secs(x) -> int:
        try:
            return max(0, int(round(int(x) / STEP)) * STEP)
        except (TypeError, ValueError):
            return 0
    out = {"id": v["did"], "start": s0, "end": t(v.get("end", start)),
           "browser": v.get("browser") or "Other", "bv": str(v.get("bv") or "")[:4],
           "os": _plain_os(v.get("os") or ""), "device": v.get("device") or "",
           "country": v.get("country") or "",
           "returning": _small(v.get("returning"), 5),
           "pages": [[t(p[0]), p[1], secs(p[2])] for p in v.get("pages") or ()
                     if isinstance(p, list) and len(p) >= 3],
           "time": secs(v.get("time") or 0),
           "downloads": [[t(d[0]), d[1]] for d in v.get("downloads") or () if isinstance(d, list) and len(d) >= 2],
           "events": [[t(e[0]), *e[1:]] for e in v.get("events") or () if isinstance(e, list) and e]}
    if v.get("acts"):
        out["acts"] = [[t(a[0]), *a[1:]] for a in v["acts"] if isinstance(a, list) and a]
    for k in ("channel", "lang", "hl", "acted", "kind", "why", "w", "e"):
        if k in v:
            out[k] = v[k]
    if "channel" in v:
        out["ref"] = site_of(v.get("ref") or "")[:80]
        out["source"] = source_of(v.get("source") or "")
        out["blang"] = _base_lang(v.get("blang") or "")
        out["screen"] = _screen_kind(v.get("screen") or "")
    return out

def swap_state(now: float | None = None) -> dict:
    """Whether what this service keeps in memory - the month keys, the
    sketches, a folder in memory (STATS_KEYS_DIR) - could reach a disk
    through the system's swap: {"state": ..., "plain": [devices]}.
    "none": no swap. "encrypted": every swap device keeps nothing readable
    once the computer restarts (FreeBSD's .eli with a one-time key, Linux's
    dm-crypt or zram). "plain": a swap device that keeps what it is given -
    said on the admin page and in the log (DEPLOY.md: encrypted swap).
    "unknown": the system could not be asked."""
    now = time.time() if now is None else now
    if _SWAP and now - _SWAP.get("at", 0) < SWAP_TTL:
        return dict(_SWAP["answer"])
    devices = _swap_devices()
    if devices is None:
        answer: dict = {"state": "unknown", "plain": []}
    elif not devices:
        answer = {"state": "none", "plain": []}
    else:
        plain = [d for d in devices if not (d.endswith(".eli") or _linux_encrypted(d))]
        answer = {"state": "plain" if plain else "encrypted", "plain": plain}
    _SWAP.clear()
    _SWAP.update(at=now, answer=answer)
    return dict(answer)

def spots(mark: str) -> tuple:
    """The two bits a mark sets: from its own hex (stats_collect's marks are
    HMAC-SHA256 cut short), else from a hash of it."""
    h = mark if HEX.fullmatch(mark or "") else hashlib.sha256((mark or "").encode()).hexdigest()
    return int(h[0:6], 16) % BITS, int(h[6:12], 16) % BITS


def add(field: int, mark: str) -> int:
    a, b = spots(mark)
    return field | (1 << a) | (1 << b)


def has(field: int, mark: str) -> bool:
    a, b = spots(mark)
    return bool((field >> a) & 1 and (field >> b) & 1)

def count(field: int) -> int:
    """How many different marks set the field (two bits each), estimated as
    a Bloom filter's: -(m/2) ln(1 - set/m)."""
    on = bin(field).count("1")
    if not on:
        return 0
    if on >= BITS:
        return BITS
    return int(round(-(BITS / 2) * math.log(1 - on / BITS)))

def funnel_of(visits: list) -> dict:
    """A day's visits as counts per way in ({channel: FUNNEL}) - what the
    admin page's "by way in" reads of a day whose visits are gone. Likely
    robots left out, as everywhere."""
    out: dict = {}
    for v in visits:
        if not isinstance(v, dict) or not v.get("pages") or v.get("kind") == "robot":
            continue
        secs = v.get("time") or 0
        _funnel_add(out, v.get("channel") or "", len(v["pages"]), secs, secs > 0,
                    bool(v.get("downloads")),
                    any(isinstance(e, list) and e[1:2] == ["donate"] for e in v.get("events") or ()))
    return out

def freeze_months(sketches: dict, frozen: dict, today: date) -> int:
    """The months before the one before this: counted into *frozen* -
    {"days", "unique", "weeks", "judged", "people", "robots"}, as the admin
    page counts them from the sketches - and their sketches deleted. A month
    counted before keeps its numbers. Returns how many months went."""
    keep_from = _month_before(today.strftime("%Y-%m"))
    months = sorted({d[:7] for d in sketches if d[:7] < keep_from})
    for m in months:
        days = sorted(d for d in sketches if d[:7] == m)
        if m not in frozen:
            entries = {d: sketches[d] if isinstance(sketches[d], dict) else {} for d in days}
            weeks: dict = {}
            for d in days:
                weeks[week_of(d)] = weeks.get(week_of(d), 0) | _net_field(entries[d])
            judged = [d for d in days if "p" in entries[d]]
            seen = sketch.union(_net_field(entries[d]) for d in days)
            all_judged = sketch.union(sketch.decode(entries[d].get("u")) for d in judged)
            net_judged = sketch.union(_net_field(entries[d]) for d in judged)
            frozen[m] = {"days": [d for d in days if "u" in entries[d]], "unique": sketch.count(seen),
                         "weeks": {w: sketch.count(f) for w, f in sorted(weeks.items())},
                         "judged": judged,
                         "people": sketch.count(sketch.union(sketch.decode(entries[d].get("p")) for d in judged)),
                         "robots": max(0, sketch.count(all_judged) - sketch.count(net_judged))}
        for d in days:
            sketches.pop(d, None)
    return len(months)


#: The lists of a day that tell who visited (countries, languages, versions,
#: sites, tags): kept with no name fewer than K_DAY once the day's visits are
#: gone - the rest is "other" (fold_day).
FOLD = ("countries", "langs", "os_versions", "browser_versions", "refs", "sources")


def fold_day(stats: dict, day: str) -> None:
    """A day's lists in FOLD, kept for good: the likely robots' part taken
    out first (as the admin page takes it), then a name counted fewer than
    K_DAY times - fewer than five different visitors brought it that day -
    said as "other". It is never added up with other days under its name:
    one person on five days is not five people. A quiet day's few visitors
    are then no longer a country, a language and a browser version side by
    side. Once."""
    d = stats["days"].get(day)
    if not isinstance(d, dict) or d.get("folded"):
        return
    robot_lists = (d.get("robots") or {}).get("lists") or {}
    for k in FOLD:
        if k not in d and k not in robot_lists:
            continue
        lst = dict(d.get(k) or {})
        for name, n in (robot_lists.pop(k, None) or {}).items():
            if lst.get(name, 0) > n:
                lst[name] -= n
            else:
                lst.pop(name, None)
        kept: dict = {}
        moved = 0
        for name, n in lst.items():
            if name == "other" or n >= K_DAY:
                kept[name] = n
            else:
                moved += n
        if moved:
            kept["other"] = kept.get("other", 0) + moved
        d[k] = kept
    d["folded"] = 1


def _forget_old(stats: dict | None = None) -> None:
    """Visits older than STATS_VISITS_DAYS: their day's counts per way in
    kept (funnel_of), then the day's file deleted - no row of a visit
    stays. The day's lists of who came are folded with it (fold_day)."""
    cutoff = (datetime.now(timezone.utc).date() - timedelta(days=VISITS_DAYS)).isoformat()
    for f in sorted(glob.glob(os.path.join(VISITS_DIR, "*.json"))):
        day = os.path.basename(f)[:10]
        if day >= cutoff:
            continue
        if stats is not None and day in (stats.get("days") or {}):
            stats["days"][day]["funnel"] = funnel_of(_load_list(f))
        _gone(f)
    if stats is not None:
        for day in sorted(stats.get("days") or {}):
            if day < cutoff:
                fold_day(stats, day)
    # The app's updates of then: counted in stats.json already, so they go.
    gone_updates = (datetime.now(timezone.utc).date() - timedelta(days=UPDATES_DAYS)).isoformat()
    for f in glob.glob(os.path.join(UPDATES_DIR, "*.json")):
        if os.path.basename(f)[:10] < gone_updates:
            _gone(f)

def _gone(path: str) -> bool:
    """*path* deleted - or, where that fails, noted in TROUBLE, said once
    in the log and tried again on the next run (sweep_left). A file that is
    not there is gone."""
    try:
        os.unlink(path)
    except FileNotFoundError:
        pass
    except OSError as e:
        if path not in TROUBLE:
            print(f"[stats] could not delete {path} ({e.strerror or type(e).__name__}) - "
                  "tried again on every run until it is gone", flush=True)
        TROUBLE[path] = e.strerror or type(e).__name__
        return False
    TROUBLE.pop(path, None)
    return True

def sweep_left(today: date | None = None) -> list:
    """What left_behind finds deleted once more; what still stays is
    returned (and in TROUBLE). What is no longer there is forgotten."""
    for path in list(TROUBLE):
        if not os.path.lexists(path):
            TROUBLE.pop(path, None)
    stays = [p for p in left_behind(today) if not _gone(p)]
    _gone_folder(ANON_DIR)
    return stays

location / {
    proxy_pass http://CONTENT_HOST:8081;   # <-- the same address as iptv.dope.rs used

    limit_req  zone=general burst=60 nodelay;
    limit_req_status 429;
    limit_conn conn_limit 64;
    limit_conn_status 429;

    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host  $host;
    proxy_set_header X-Forwarded-Port  443;
}

# -- error reports and feedback from the app (donate/feedback.py) --------
location = /feedback/report {
    limit_req zone=iptv_feedback burst=10 nodelay;
    limit_req_status 429;
    limit_except POST { deny all; }
    client_max_body_size 256k;
    client_body_buffer_size 256k;
    proxy_pass http://unix:/var/run/iptv_donate/donate.sock;
    proxy_set_header X-Real-IP $http_x_real_ip;
    proxy_set_header X-Admin-User "";
    proxy_connect_timeout 3s;
    proxy_read_timeout 15s;
    add_header X-Robots-Tag "noindex, nofollow" always;
}

: ${iptv_donate_enable:=NO}
: ${iptv_donate_user:=iptv}
: ${iptv_donate_socket_group:=www}
: ${iptv_donate_python:=/usr/local/bin/python3}
: ${iptv_donate_script:=/usr/local/www/iptv/donate/donate.py}
: ${iptv_donate_log:=/var/log/iptv-donate.log}

# rc.subr runs the command as ${iptv_donate_user} (su -m) because that
# variable is set, so daemon(8) needs no -u of its own: given one, it tried
# to switch users again without root ("failed to set user environment").
# Running as that user, it can only write its pidfile into a directory of
# that user's, made here as root before the start ("Permission denied" in
# /var/run itself). The service's socket is there too: the folder is the
# service's and nginx's workers' group's (iptv_donate_socket_group, www -
# the service's SOCKET_GROUP names the same), 0750, so only they reach the
# socket in it (0660, made there with the folder's group); it was 0755
# around a socket anyone in the jail could connect to.
piddir=/var/run/${name}
pidfile=${piddir}/${name}.pid
command=/usr/sbin/daemon
command_args="-R 5 -H -P ${pidfile} -o ${iptv_donate_log} ${iptv_donate_python} -I ${iptv_donate_script}"
start_precmd=iptv_donate_precmd

iptv_donate_precmd()
{
	install -d -o "${iptv_donate_user}" -g "${iptv_donate_socket_group}" -m 750 "${piddir}"
}

class SocketNotPrivate(Exception):
    """The socket cannot be kept to nginx's workers and this service: the
    service does not start (main). Its words say why, for the log."""


def open_to_nginx(path: str, group: str = SOCKET_GROUP) -> str:
    """The socket at *path* for nginx's workers and this service alone:
    its group *group*, mode 0660. In the rc file's folder (iptv:www 0750) a
    new file already has the folder's group, as FreeBSD gives every new
    file; elsewhere it is given it. Where the group does not exist, or this
    user may not give it (it is not one of the group's), it fails closed:
    SocketNotPrivate, the socket as it was made (0660, never wider), and
    the service does not start - there is no way to open it to every user.
    What was done, for the start line."""
    import grp
    try:
        gid = grp.getgrnam(group).gr_gid if group else None
    except KeyError:
        gid = None
    if gid is not None:
        try:
            if os.stat(path).st_gid != gid:
                os.chown(path, -1, gid)
            os.chmod(path, 0o660)
            return f"0660, group {group}"
        except OSError:
            pass
    if gid is not None:
        why = f"the group {group!r} could not be given"
    elif group:
        why = f"no group {group!r} here"
    else:
        why = "SOCKET_GROUP is empty"
    raise SocketNotPrivate(
        f"the socket {path} cannot be nginx's and this service's alone: {why}. SOCKET_GROUP in "
        f"{CONFIG_FILE} names the group nginx's workers run as, the same as the rc file's "
        "iptv_donate_socket_group (on a developer's machine, a group of its own user's)")

# Nothing of who asked what is written down here (the privacy policy,
# section 9): no access log, and the error log only for what stops the
# server - a refused or broken request would name its address. The
# content server keeps what the statistics read, for two days.
access_log off;
error_log /var/log/nginx/error.log crit;

# Nothing of who asked what is written down here (the privacy policy,
# section 9): no access log, and the error log only for what stops the
# server - a refused or broken request would name its address. The
# content server keeps what the statistics read, for two days.
access_log off;
error_log /var/log/nginx/error.log crit;

# Nothing of who asked what is written down here (the privacy policy,
# section 9): no access log, and the error log only for what stops the
# server - a refused or broken request would name its address. The
# content server keeps what the statistics read, for two days.
access_log off;
error_log /var/log/nginx/error.log crit;

# Nothing of who asked what is written down here (the privacy policy,
# section 9): no access log, and the error log only for what stops the
# server - a refused or broken request would name its address. The
# content server keeps what the statistics read, for two days.
access_log off;
error_log /var/log/nginx/error.log crit;

# Nothing of who asked what is written down here (the privacy policy,
# section 9): no access log, and the error log only for what stops the
# server - a refused or broken request would name its address. The
# content server keeps what the statistics read, for two days.
access_log off;
error_log /var/log/nginx/error.log crit;

# dl.php's file name: the last path segment of ?f=, never one starting with
# a dot, at most 120 characters (a release's longest is under 50). Anything
# else is answered 404.
map $arg_f $iptv_dl_file {
    default "";
    "~^(?:.*/)?(?<iptv_f>[A-Za-z0-9_~-][A-Za-z0-9._~-]{0,119})$" $iptv_f;
}

# -- statistics -----------------------------------------------------------------
# One line per page view (only / and /help/), per /hit and per download,
# handed to the donate service over its socket (access_log syslog:...
# below; donate/stats_inbox.py) - never written to a file. The lines wait in
# the service's memory until its own thread counts them, a minute at most:
# counts per day and, for the admin page's visitor log, each visit without
# its address (see donate/stats_collect.py's docstring for what is kept and
# how long). So no log anywhere holds a visitor's address. The page that
# linked here is not sent at all: the page's own /hit says it, as the
# statistics read it (its site, its path without the query). Each value is
# cut so a line fits one datagram (2 KiB, FreeBSD's default).
# Of the rest of the sender's own words, as much as the statistics read: the
# browser's name to 512 characters (stats_collect.py's UA_MAX), the address
# asked for to 1024, the method to 16 - each could be 8k, a line 24k and
# more of whatever was sent.
map $request_method $iptv_log_method {
    default "";
    "~^(?<iptv_log_m1>.{1,16})" $iptv_log_m1;
}
map $http_user_agent $iptv_log_ua {
    default "";
    "~^(?<iptv_log_ua1>.{1,512})" $iptv_log_ua1;
}
# Of the address asked for, only what the statistics read. A page (/,
# /help/): its path - never its query, which can carry whatever a link
# put there (?fbclid=, ?utm_..., a ?lang= the page's language "l" says
# already). /hit: the fields the page's signal sends (nav.js) and
# stats_collect.py reads, each as sent and in this order - one left out is
# empty, which the statistics read as not sent - and nothing else of its
# query; the page that linked last, the longest, so the cut below takes it
# before the rest. Lines from before have the whole address; the
# statistics read both alike.
map $request_uri $iptv_log_uri_kept {
    default "";
    "~^/hit(?:\?|$)" "/hit?p=$arg_p&ev=$arg_ev&t=$arg_t&x=$arg_x&n=$arg_n&s=$arg_s&l=$arg_l&bl=$arg_bl&w=$arg_w&h=$arg_h&hl=$arg_hl&r=$arg_r";
    "~^(?<iptv_log_path>[^?]+)" $iptv_log_path;
}
map $iptv_log_uri_kept $iptv_log_uri {
    default "";
    "~^(?<iptv_log_uri1>.{1,1024})" $iptv_log_uri1;
}
log_format iptv_stats escape=json
    '{"ip":"$http_x_real_ip","t":"$time_iso8601","m":"$iptv_log_method",'
    '"u":"$iptv_log_uri","s":$status,"a":"$iptv_log_ua","l":"$iptv_lang"}';
# A browser that has opened the admin page (donate.py sets iptv_nostats) is
# the site's owner testing: neither its page views nor its downloads are
# logged, so neither the statistics nor the public download counter count it.
map $cookie_iptv_nostats $iptv_count {
    default 1;
    "1"     0;
}
# A download, for the statistics (to the service's socket, as above):
# nginx's "combined" with the visitor's address as a last field
# ($remote_addr is the TLS proxy), so stats_collect.py can count a visitor
# once per file per day - and no page that linked ("-"). Of the request
# line only the method, the file's name ($iptv_dl_file: the last part of
# ?f=, 120 characters at the most, "" for one that is no file's) and the
# protocol - nothing else the link carried. The browser's name cut short as
# above; no user name ("-" where combined has $remote_user).
log_format iptv_dl '$remote_addr - - [$time_local] "$iptv_log_method /dl.php?f=$iptv_dl_file $server_protocol" '
    '$status $body_bytes_sent "-" "$iptv_log_ua" "$http_x_real_ip"';
# The public download counter's own log (sync-releases.sh counts it into
# downloads.json): the request line as above, the answer, and what asked -
# the app, a robot that says so, nothing, or a browser ($iptv_ua_kind) -
# and nothing else: no address, no time, no browser's name.
map $http_user_agent $iptv_ua_kind {
    default "browser";
    ""      "none";
    "-"     "none";
    "~*^dopeiptv/" "app";
    "~*(bot|crawl|spider|slurp|preview|facebookexternalhit|whatsapp|telegram|discord|skype|embed|monitor|scan)" "robot";
}
log_format iptv_dl_count '"$iptv_log_method /dl.php?f=$iptv_dl_file $server_protocol" $status $iptv_ua_kind';

# -- the pages ------------------------------------------------------------
# No-cache: a returning visitor always checks for a new page (a new
# release, new counts) - the PHP pages were never cached either.
location = / {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Vary $iptv_vary;
    add_header Set-Cookie $iptv_set_cookie;
    add_header Cache-Control "no-cache";
    try_files /i18n/$iptv_lang/index.html =404;
}
location = /help/ {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Vary $iptv_vary;
    add_header Set-Cookie $iptv_set_cookie;
    add_header Cache-Control "no-cache";
    try_files /i18n/$iptv_lang/help/index.html =404;
}

# Every download link goes through /dl.php?f=NAME, which sends the browser
# on to /files/NAME. Only a file that is there; anything else is plain
# "Not found". These requests go to the statistics (the service's socket)
# and to a log of their own without an address, where sync-releases.sh
# counts the downloads (newsyslog keeps .0 uncompressed for it, see
# DEPLOY.md).
#
# Counted against iptv_dl first, then answered in @iptv_dl: nginx runs a
# location's return before its limit_req (the rewrite phase comes before
# the one limits are checked in), so a limit beside a return is never
# applied - try_files hands on only after it. /.iptv-none is never there.
location = /dl.php {
    limit_req zone=iptv_dl burst=60 nodelay;
    limit_req_status 429;
    try_files /.iptv-none @iptv_dl;
}
location @iptv_dl {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_dl iptv_dl if=$iptv_count;
    access_log /var/log/nginx/iptv.dope.rs-dl-counts.log iptv_dl_count if=$iptv_count;
    default_type text/plain;
    if ($iptv_dl_file = "") {
        return 404 "Not found";
    }
    if ($iptv_dl_nightly != "") {
        return 302 https://github.com/slimture/dopeIPTV/releases/download/$iptv_dl_nightly/$iptv_dl_file;
    }
    if (!-f $document_root/files/$iptv_dl_file) {
        return 404 "Not found";
    }
    return 302 /files/$iptv_dl_file;
}

# -- statistics -------------------------------------------------------------
# A page tells /hit when it is shown in a browser, how long it was looked
# at, the tip dialog's opening (nav.js) and a support link's click
# (events.js); only the log line counts.
# Counted first, then answered in @iptv_hit, as /dl.php is: beside the
# return the limit was never applied.
location = /hit {
    limit_req zone=iptv_hit burst=60 nodelay;
    limit_req_status 429;
    client_max_body_size 1k;
    try_files /.iptv-none @iptv_hit;
}
location @iptv_hit {
    access_log syslog:server=unix:/var/run/iptv_donate/stats.sock,nohostname,tag=iptv_stats iptv_stats if=$iptv_count;
    add_header Cache-Control "no-store" always;
    add_header X-Robots-Tag "noindex, nofollow" always;
    return 204;
}

# /hit: what a page tells when it is shown (nav.js) - a few per visit.
limit_req_zone $http_x_real_ip zone=iptv_hit:1m rate=120r/m;
# /dl.php: a click on a download, the app fetching its update - a few per
# visitor; room for many on one address all the same.
limit_req_zone $http_x_real_ip zone=iptv_dl:1m rate=120r/m;
# The admin page, a little more patient than /donate/: a browser that holds
# the session cookie is not counted (an empty key is not) - every file of
# the page counted, and a few reloads on the phone used the minute up and
# left the page without its stylesheet and script. A forged cookie gets
# nothing (donate.py checks its signature).
map $cookie_iptv_admin $iptv_admin_limit {
    ""         $http_x_real_ip;
    default    "";
}
# A page opened in the browser (typed, a bookmark, a link, the Home Screen
# app), not the page's own requests for its data: those say "cors" or "same-
# origin", and a browser too old to say ask for anything but HTML first.
map "$http_sec_fetch_mode|$http_accept" $iptv_admin_page {
    "~^navigate\|"   1;
    "~^\|text/html"  1;
    default          "";
}
# A zone's key cannot change on a reload (nginx -t passes, the reload fails,
# the old configuration keeps running): a new key needs a new zone name.
limit_req_zone $iptv_admin_limit zone=iptv_admin:1m rate=30r/m;
# ...and every request by its address, cookie or not: nginx cannot tell a
# made-up iptv_admin cookie from a real one (donate.py can, but only after
# nginx has asked it), so one sent along was never counted. Far more than
# the admin page asks for, signed in, on every device at once.
limit_req_zone $http_x_real_ip zone=iptv_admin_addr:1m rate=600r/m;
# Signing in (/admin/auth/): counted for everyone, cookie or not. donate.py
# also holds back an address or a name after ten failures in 15 minutes.
limit_req_zone $http_x_real_ip zone=iptv_signin:1m rate=20r/m;

# A sync copy (up to 3 MB) is held in memory while it comes in, below: a few
# at once from one address, never more. Only a PUT is counted: a GET or a
# DELETE has an empty key, which is not.
map $request_method $dopeiptv_sync_put {
    default              "";
    PUT                  $binary_remote_addr;
}
limit_conn_zone $dopeiptv_sync_put zone=dopeiptv_sync_put:1m;

# A request's body held in memory, never in nginx's temp folder on disk:
# 256k, the most the content server lets in anywhere but /sync/ (for a
# feedback report); /sync/ and /together/ have their own below.
client_max_body_size    256k;
client_body_buffer_size 256k;
# ...and an answer too: a sync copy can be 2 MB, and one larger than
# nginx's buffers in memory is passed on as it comes, instead of being
# written to /var/tmp to be sent from there. Every location below takes
# this (/together/ buffers nothing at all); the other servers of the
# site only send visitors on.
proxy_max_temp_file_size 0;

# Who shares an address - a phone network (CGNAT), a school, an office,
# a household - must never be turned away for being many. The files a
# page is made of (styles, scripts, fonts, pictures, the release list the
# app checks) are cheap for nginx and are not counted at all; the pages
# themselves have a generous allowance, and what the services behind
# answer (/donate/, /feedback/, /admin/, /hit) has a limit of its own
# on the content host. A request over a limit is told 429 (slow down),
# never 503 (which reads as the site being down).
location ~* \.(?:css|js|mjs|svg|png|jpe?g|webp|avif|gif|ico|woff2?|ttf|webmanifest|json|txt|xml|map)$ {
    proxy_pass http://CONTENT_HOST:8081;   # <-- the same address as below
    limit_conn conn_limit 64;
    proxy_set_header Host              $host;
    proxy_set_header X-Real-IP         $remote_addr;
    proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-Host  $host;
    proxy_set_header X-Forwarded-Port  443;
}

# Where the address may not leave the site: the admin pages, the support
# page (Stripe sends people back to it with their checkout's id) and the
# Trakt sign-in's way back to the app.
map $uri $dopeiptv_referrer {
    default              "strict-origin-when-cross-origin";
    ~^/admin(?:/|$)      "no-referrer";
    ~^/support(?:/|$)    "no-referrer";
    ~^/trakt/            "no-referrer";
}
# The admin pages in a window of their own: a page they open, or one that
# opened them, cannot reach into them (Cross-Origin-Opener-Policy). Not the
# rest of the site: a payment's window (Google Pay's, a bank's check) may
# talk back to the page that opened it.
map $uri $dopeiptv_coop {
    default              "";
    ~^/admin(?:/|$)      "same-origin";
}
# What only the site's own pages and the app read - the admin pages and the
# services' answers - never loaded into another site's page as an image or
# a script (Cross-Origin-Resource-Policy). The app is not a browser and
# never sees it; the pages, files and downloads stay for everyone.
map $uri $dopeiptv_corp {
    default                                   "";
    ~^/admin(?:/|$)                           "same-origin";
    ~^/(?:sync|together|feedback|donate)/     "same-origin";
    ~^/(?:support/key|hit)$                   "same-origin";
}

# https only, for a year, the names under it too, as the proxy's http
# block says for every site; never in a frame of another site; a file's type is
# what it is sent as, never guessed (a download is never run as a
# script); the address kept to the site where it says so (the map).
add_header Content-Security-Policy   $csp_policy always;
add_header Content-Security-Policy   "frame-ancestors 'none'" always;
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
add_header X-Content-Type-Options    "nosniff" always;
add_header X-Frame-Options           "DENY" always;
add_header Referrer-Policy           $dopeiptv_referrer always;
proxy_hide_header Referrer-Policy;
# No page of the site, nor a frame in it, may use what the site never
# does - left alone: payment (Apple Pay, Google Pay), passkeys
# (publickey-credentials-*), copying (clipboard-write), sharing a link
# (web-share), and whatever else is not named.
add_header Permissions-Policy        "camera=(), microphone=(), geolocation=(), display-capture=(), usb=(), serial=(), hid=(), bluetooth=(), midi=(), idle-detection=(), xr-spatial-tracking=(), browsing-topics=()" always;
add_header Cross-Origin-Opener-Policy   $dopeiptv_coop always;
add_header Cross-Origin-Resource-Policy $dopeiptv_corp always;

# nginx's version in no answer, its error pages included.
server_tokens off;

# https only, for a year, as dopeiptv.org's: an old link typed or saved
# as http:// is not asked in the clear again.
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

# Chosen by ?lang=: remembered - sent over https only (the site has no
# other), and not along when another site's page posts here or loads a
# part of it. Chosen otherwise: varies by visitor.
map $iptv_lang_arg $iptv_set_cookie {
    "" "";
    default "lang=$iptv_lang_arg; Max-Age=31536000; path=/; Secure; SameSite=Lax";
}

# A name that starts with a dot is never the site's: the deploy copies
# public/.gitignore and public/files/.gitignore along, and an editor or
# a checkout can leave more (.git/, .env, .swp). Only /.well-known/ is
# meant to be read, by name below. The first regex location, so no
# other one (a .css, a .png) answers for such a name first.
location ~ /\.(?!well-known/) {
    return 404;
}
# How to report a security problem (RFC 9116); its Expires is renewed
# once a year (donate/test_deploy_content.py fails once it has passed).
location = /.well-known/security.txt {
    types { }
    default_type text/plain;
    add_header Cache-Control "public, max-age=86400";
    try_files $uri =404;
}
